import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import {
  AlertCircle, ArrowRight, BarChart3, CalendarClock, Check, CheckCircle2, ChevronRight, CircleDot,
  Copy, CreditCard, Download, ExternalLink, Eye, FileCheck2, FileText,
  Filter, Gauge, Globe2, KeyRound, LayoutDashboard, LockKeyhole, Menu, Moon, MoreHorizontal,
  Pause, Play, Plus, RefreshCw, Search, Settings, ShieldCheck, Sparkles, Sun, TerminalSquare, TriangleAlert,
  UserRound, UsersRound, X, XCircle, Zap,
} from 'lucide-react';
import logoLightUrl from '../easyacrlogo.svg';
import logoDarkUrl from '../easyacrlogo-reversed.svg';
import { acrs, deadlines, draftPlans, entitlements, issues, roleLabels, scans, schedules, type Role, type ScanStatus, type Severity } from './domain';

type Navigate = (path: string) => void;

function useRouter() {
  const [path, setPath] = useState(window.location.pathname);
  useEffect(() => {
    const onPop = () => setPath(window.location.pathname);
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);
  const navigate: Navigate = (next) => {
    window.history.pushState({}, '', next);
    setPath(next);
    window.scrollTo({ top: 0, behavior: 'instant' });
  };
  return { path, navigate };
}

function Link({ to, navigate, children, className, current }: { to: string; navigate: Navigate; children: ReactNode; className?: string; current?: boolean }) {
  return <a href={to} className={className} aria-current={current ? 'page' : undefined} onClick={(event) => { if (!event.metaKey && !event.ctrlKey) { event.preventDefault(); navigate(to); } }}>{children}</a>;
}

function Logo({ navigate, reversed = false }: { navigate: Navigate; reversed?: boolean }) {
  return <Link to="/" navigate={navigate} className={`brand-lockup ${reversed ? 'is-reversed' : ''}`}><img className="logo logo-on-light" src={logoLightUrl} alt="easyACR" /><img className="logo logo-on-dark" src={logoDarkUrl} alt="easyACR" /></Link>;
}

function ThemeButton({ theme, setTheme }: { theme: 'light' | 'dark'; setTheme: (value: 'light' | 'dark') => void }) {
  return <button className="theme-button" type="button" onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} aria-label={`Use ${theme === 'light' ? 'dark' : 'light'} theme`}>{theme === 'light' ? <Moon size={20} /> : <Sun size={20} />}</button>;
}

function PublicShell({ path, navigate, theme, setTheme, children }: { path: string; navigate: Navigate; theme: 'light' | 'dark'; setTheme: (value: 'light' | 'dark') => void; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  return <>
    <a className="skip-link" href="#main">Skip to main content</a>
    <header className="public-header">
      <div className="container">
        <Logo navigate={navigate} />
        <nav id="public-menu" className={`public-nav ${open ? 'open' : ''}`} aria-label="Primary">
          {['/features', '/pricing', '/about'].map((to) => <Link key={to} to={to} navigate={navigate} current={path === to}>{to.slice(1)[0].toUpperCase() + to.slice(2)}</Link>)}
          <Link to="/sign-in" navigate={navigate}>Sign in</Link>
          <Link to="/sign-up" navigate={navigate} className="button small">Start trial</Link>
        </nav>
        <div className="cluster">
          <ThemeButton theme={theme} setTheme={setTheme} />
          <button className="menu-button" type="button" aria-expanded={open} aria-controls="public-menu" onClick={() => setOpen(!open)}><span className="sr-only">Menu</span>{open ? <X size={22} /> : <Menu size={22} />}</button>
        </div>
      </div>
    </header>
    <main id="main">{children}</main>
    <footer className="footer"><div className="container spaced"><Logo navigate={navigate} /><p className="muted">Evidence for better accessibility decisions. Not a certification service.</p><nav className="cluster" aria-label="Footer"><Link to="/features" navigate={navigate}>Features</Link><Link to="/pricing" navigate={navigate}>Pricing</Link><Link to="/about" navigate={navigate}>About</Link></nav></div></footer>
  </>;
}

const productFeatures = [
  { icon: <Globe2 />, title: 'Focused site scans', copy: 'Crawl public or authenticated web experiences with explicit page, pattern, and schedule controls.' },
  { icon: <BarChart3 />, title: 'Evidence-rich reports', copy: 'Move from executive trends to affected pages, elements, criteria, code excerpts, and remediation guidance.' },
  { icon: <FileCheck2 />, title: 'Draft ACR workspace', copy: 'Use the appropriate current VPAT edition, map evidence, flag manual review, and keep a version trail.' },
  { icon: <TerminalSquare />, title: 'WebMCP tools', copy: 'Let entitled AI clients use clearly authorized easyACR tools through an experimental, replaceable adapter.' },
  { icon: <CalendarClock />, title: 'Scheduled assurance', copy: 'Run recurring scans, see the next run in your timezone, and monitor changes over time.' },
  { icon: <ShieldCheck />, title: 'Security boundaries', copy: 'Keep credentials out of URLs and client storage while isolating crawl execution and organization data.' },
];

function Home({ navigate }: { navigate: Navigate }) {
  return <>
    <section className="hero"><div className="container hero-grid"><div className="stack"><span className="eyebrow">Accessibility evidence, organized</span><h1>Turn accessibility findings into procurement-ready evidence.</h1><p>easyACR helps software teams scan web products, understand what needs attention, and prepare draft Accessibility Conformance Reports for US and EU buyers.</p><div className="cluster"><Link className="button" to="/sign-up" navigate={navigate}>Start a 14-day trial <ArrowRight size={18} /></Link><Link className="button secondary" to="/features" navigate={navigate}>Explore the workflow</Link></div><small>No credit card for the prototype trial. Draft pricing and limits are product assumptions.</small></div><div className="hero-card stack"><div className="spaced"><div><span className="eyebrow">Latest scan</span><h3>docs.northstar.example</h3></div><Status value="completed" /></div><div className="grid-3"><MiniMetric label="Pages" value="184" /><MiniMetric label="Violations" value="12" /><MiniMetric label="Needs review" value="7" /></div><div><div className="spaced"><strong>Evidence readiness</strong><span>78%</span></div><div className="progress" role="progressbar" aria-label="Evidence readiness" aria-valuemin={0} aria-valuemax={100} aria-valuenow={78}><span style={{ width: '78%' }} /></div></div><div className="callout warning"><strong>Human review remains required</strong><p>Automated checks cannot determine complete conformance or certify a product.</p></div></div></div></section>
    <section className="section section-alt"><div className="container"><div className="section-heading"><span className="eyebrow">One connected workspace</span><h2>From first crawl to reviewed draft</h2><p>Keep automated evidence, manual evaluation, remediation context, and report decisions traceable without pretending automation can make the final call.</p></div><div className="grid-3">{productFeatures.map((feature) => <article className="card" key={feature.title}><div className="feature-icon">{feature.icon}</div><h3>{feature.title}</h3><p>{feature.copy}</p></article>)}</div></div></section>
    <section className="section"><div className="container grid-2"><div className="stack"><span className="eyebrow">Built for consequential decisions</span><h2>Clear about what the evidence can—and cannot—prove.</h2><p>easyACR distinguishes automatically detected findings from criteria that require a person to evaluate context, behavior, and usability.</p><ul><li>Every finding includes detection method and evidence.</li><li>Inconclusive criteria are marked “Needs review.”</li><li>A human review gate is required before reviewed export.</li></ul></div><div className="card-flat stack"><h3>Security posture, at a glance</h3>{['Server-side URL and redirect policy', 'Isolated scanner workers', 'Encrypted, minimized secret retention', 'Organization-scoped authorization', 'Sanitized evidence excerpts and audit events'].map((item) => <div className="cluster" key={item}><CheckCircle2 color="var(--success)" size={20} aria-hidden="true" /><span>{item}</span></div>)}<Link to="/about" navigate={navigate}>Read the prototype boundaries <ArrowRight size={14} /></Link></div></div></section>
  </>;
}

function Features() { return <section className="section"><div className="container"><div className="section-heading"><span className="eyebrow">Product capabilities</span><h1>Evidence your team can act on</h1><p>Purpose-built workflows for scanning, issue exploration, scheduling, draft ACR preparation, and carefully authorized AI-client access.</p></div><div className="grid-3">{productFeatures.map((feature) => <article className="card" key={feature.title}><div className="feature-icon">{feature.icon}</div><h2 style={{ fontSize: '1.4rem' }}>{feature.title}</h2><p>{feature.copy}</p><span className="badge info"><Check size={14} /> Included in prototype</span></article>)}</div><div className="callout warning" style={{ marginTop: 32 }}><strong>A scan is not a certification.</strong><p>Automated rules identify a valuable subset of accessibility barriers. Complete evaluation requires skilled human judgment, assistive-technology testing, and product context.</p></div></div></section>; }

function Pricing({ navigate }: { navigate: Navigate }) { return <section className="section"><div className="container"><div className="section-heading"><span className="eyebrow">Draft pricing assumptions</span><h1>Plans for teams at every stage</h1><p>These amounts, limits, and package names are placeholder product assumptions, centralized for replacement before launch.</p></div><div className="grid-3">{draftPlans.map((plan) => <article className={`card pricing-card ${plan.featured ? 'featured' : ''}`} key={plan.name}>{plan.featured && <span className="badge info">Most complete prototype</span>}<h2 style={{ marginTop: 12 }}>{plan.name}</h2><p><strong style={{ fontSize: '2.3rem', color: 'var(--heading)' }}>{plan.price}</strong> / month</p><span className="badge warning">{plan.note}</span><p>{plan.pages}</p><ul>{plan.features.map((feature) => <li key={feature}>{feature}</li>)}</ul><Link className="button" to="/sign-up" navigate={navigate}>Choose {plan.name}</Link></article>)}</div><p className="muted" style={{ marginTop: 24 }}>Taxes, annual billing, overages, procurement terms, and service-level commitments remain unresolved product decisions.</p></div></section>; }

function About() { return <section className="section"><div className="container"><div className="section-heading"><span className="eyebrow">About easyACR</span><h1>Better evidence. Better conversations.</h1><p>easyACR is a prototype for software companies responding to accessibility expectations in government and EU procurement.</p></div><div className="grid-2"><article className="card"><h2>What it does</h2><p>Organizes repeatable scan evidence, manual-review work, issue context, and draft ACR content in one role-aware workspace.</p></article><article className="card"><h2>What it does not do</h2><p>It does not certify conformance, replace qualified evaluators, provide legal advice, or turn automated findings into unsupported conformance claims.</p></article><article className="card full"><h2>Prototype security model</h2><p>Secrets cross an application-server boundary once and never return to the browser. A production scanner would enforce address classification before and after DNS resolution, restrict redirects and protocols, block private/link-local/metadata networks, isolate egress, and sanitize all captured excerpts.</p></article></div></div></section>; }

function AuthPage({ kind, navigate }: { kind: 'sign-in' | 'sign-up' | 'recovery' | 'checkout'; navigate: Navigate }) {
  const content = {
    'sign-in': { title: 'Welcome back', copy: 'Sign in to your easyACR workspace.', button: 'Sign in' },
    'sign-up': { title: 'Create your account', copy: 'Start with a 14-day prototype trial.', button: 'Create account' },
    recovery: { title: 'Recover your account', copy: 'We’ll send a time-limited recovery link.', button: 'Send recovery link' },
    checkout: { title: 'Your trial is ready', copy: 'No payment was processed in this prototype.', button: 'Continue to onboarding' },
  }[kind];
  const submit = (event: FormEvent) => { event.preventDefault(); navigate(kind === 'checkout' ? '/onboarding' : kind === 'recovery' ? '/sign-in' : '/onboarding'); };
  return <main className="auth-shell" id="main"><section className="auth-brand stack"><Logo navigate={navigate} /><span className="eyebrow" style={{ color: '#f7c371' }}>Evidence, not empty promises</span><h1>{kind === 'sign-in' ? 'Continue the work.' : 'Start with a clearer accessibility picture.'}</h1><p>Automated scans inform decisions. Human review completes the evaluation.</p></section><section className="auth-form"><div className="stack"><div><h2>{content.title}</h2><p>{content.copy}</p></div>{kind === 'checkout' ? <div className="callout success"><strong>Checkout result: success</strong><p>Team plan trial · $0 charged · 14 days</p></div> : <form className="stack" onSubmit={submit} noValidate><div className="field"><label htmlFor="email">Work email</label><input id="email" name="email" type="email" autoComplete="email" required placeholder="name@company.example" /></div>{kind !== 'recovery' && <div className="field"><label htmlFor="password">Password</label><input id="password" name="password" type="password" autoComplete={kind === 'sign-in' ? 'current-password' : 'new-password'} required minLength={12} /><p className="hint">Use at least 12 characters. Prototype values are never persisted.</p></div>}{kind === 'sign-up' && <label className="cluster"><input type="checkbox" required /> I agree to the prototype terms and privacy notice.</label>}<button className="button" type="submit">{content.button} <ArrowRight size={18} /></button></form>}{kind === 'checkout' && <button className="button" type="button" onClick={() => navigate('/onboarding')}>{content.button} <ArrowRight size={18} /></button>}<div className="spaced">{kind === 'sign-in' ? <><Link to="/password-recovery" navigate={navigate}>Forgot password?</Link><Link to="/sign-up" navigate={navigate}>Create account</Link></> : <Link to="/sign-in" navigate={navigate}>Back to sign in</Link>}</div><small>Prototype authentication adapter · no real account or payment is created.</small></div></section></main>;
}

function Status({ value }: { value: ScanStatus | string }) {
  const icon = value === 'completed' || value === 'Active' ? <CheckCircle2 size={14} /> : value === 'running' ? <RefreshCw size={14} /> : value === 'failed' || value === 'canceled' ? <XCircle size={14} /> : <AlertCircle size={14} />;
  return <span className={`status ${value.replace(' ', '-')}`}>{icon}<span>{value === 'partial' ? 'Partial result' : value.replace('-', ' ')}</span></span>;
}

function SeverityLabel({ value }: { value: Severity }) { return <span className={`severity ${value}`}>{value === 'critical' || value === 'serious' ? <TriangleAlert size={17} /> : <CircleDot size={17} />}{value}</span>; }
function MiniMetric({ label, value }: { label: string; value: string }) { return <div><div className="metric-value" style={{ fontSize: '1.7rem' }}>{value}</div><div className="metric-label">{label}</div></div>; }
function PageHeading({ eyebrow, title, copy, action }: { eyebrow?: string; title: string; copy?: string; action?: ReactNode }) { return <header className="page-heading spaced"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{copy && <p>{copy}</p>}</div>{action}</header>; }
function MobileLabel({ children }: { children: ReactNode }) { return <span className="mobile-label">{children}</span>; }

const navItems = [
  ['/dashboard', 'Dashboard', LayoutDashboard], ['/scans', 'Scans', Gauge], ['/schedules', 'Schedules', CalendarClock], ['/acrs', 'Draft ACRs', FileText], ['/tools', 'Tools · WebMCP', TerminalSquare], ['/account', 'Account', UserRound], ['/billing', 'Subscription', CreditCard], ['/organization', 'Organization', UsersRound],
] as const;

function AppShell({ path, navigate, role, setRole, theme, setTheme, children }: { path: string; navigate: Navigate; role: Role; setRole: (role: Role) => void; theme: 'light' | 'dark'; setTheme: (value: 'light' | 'dark') => void; children: ReactNode }) {
  const [open, setOpen] = useState(false);
  const access = entitlements[role];
  return <div className="app-shell"><a className="skip-link" href="#main">Skip to main content</a><aside className={`sidebar ${open ? 'open' : ''}`} aria-label="Application navigation"><div className="spaced"><Logo navigate={navigate} />{open && <button className="icon-button" onClick={() => setOpen(false)} aria-label="Close menu"><X size={20} /></button>}</div><nav className="app-nav">{navItems.filter(([to]) => to !== '/organization' || access.organization).map(([to, label, Icon]) => <Link key={to} to={to} navigate={(next) => { setOpen(false); navigate(next); }} current={path === to || (to === '/scans' && path.startsWith('/scans/')) || (to === '/acrs' && path.startsWith('/acrs/'))}><Icon size={19} aria-hidden="true" />{label}</Link>)}</nav><div className="sidebar-footer"><div className="card-flat stack-sm"><strong>Demo role</strong><label className="field"><span className="sr-only">Select demo role</span><select value={role} onChange={(event) => setRole(event.target.value as Role)}>{Object.entries(roleLabels).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label></div><small>Mock mode · no production services</small></div></aside><div className="app-main"><header className="app-topbar"><div className="cluster"><button className="menu-button" type="button" onClick={() => setOpen(true)} aria-label="Open navigation"><Menu size={22} /></button><strong>Northstar Labs</strong><span className="badge info">{roleLabels[role]}</span></div><div className="cluster"><ThemeButton theme={theme} setTheme={setTheme} /><div className="avatar" aria-label="Signed in as Avery Reed">AR</div></div></header><main id="main" className="app-content">{children}</main></div></div>;
}

function Gate({ allowed, title, children, navigate }: { allowed: boolean; title: string; children: ReactNode; navigate: Navigate }) {
  if (allowed) return <>{children}</>;
  return <><div className="locked" aria-hidden="true"><div className="grid-3"><div className="card"><h3>Protected capability</h3><p>Representative content</p></div><div className="card"><h3>Plan limit</h3><p>Upgrade required</p></div><div className="card"><h3>Server enforced</h3><p>Not just hidden in the UI</p></div></div></div><section className="card upgrade-panel"><LockKeyhole size={36} /><h2>{title}</h2><p>Your current demo role does not include this capability. Entitlements are evaluated centrally and must also be enforced by the application server.</p><Link className="button" to="/billing" navigate={navigate}>Compare plans</Link></section></>;
}

function Dashboard({ navigate, role }: { navigate: Navigate; role: Role }) {
  const access = entitlements[role];
  return <><PageHeading eyebrow="Overview" title="Good afternoon, Avery" copy="Here’s the current accessibility evidence across Northstar Labs." action={<button className="button" disabled={!access.scan} onClick={() => navigate('/scans/new')}><Plus size={18} /> Run a scan</button>} />{role === 'trial' && <div className="callout warning"><strong>3 days and 9 pages remain in your trial.</strong><p>WebMCP and scheduled scans are not included in this trial configuration. <Link to="/billing" navigate={navigate}>Review plans</Link></p></div>}{role === 'free' && <div className="callout"><strong>Your account is ready.</strong><p>Choose a trial or paid plan to run scans and create draft ACRs.</p></div>}<div className="grid-4" style={{ marginTop: 20 }}><article className="card metric"><span className="metric-label">Pages scanned</span><span className="metric-value">313</span><span className="trend">↓ 12% from prior period</span></article><article className="card metric"><span className="metric-label">Open violations</span><span className="metric-value">95</span><span className="muted">29 automatically detected</span></article><article className="card metric"><span className="metric-label">Latest status</span><span><Status value="running" /></span><span className="muted">64% · 78 of 122 pages</span></article><article className="card metric"><span className="metric-label">Plan status</span><span className="metric-value" style={{ fontSize: '1.45rem' }}>{roleLabels[role]}</span><Link to="/billing" navigate={navigate}>Manage subscription</Link></article></div><section className="grid-2" style={{ marginTop: 24 }}><article className="card"><div className="spaced"><h2 style={{ fontSize: '1.5rem' }}>Recent scans</h2><Link to="/scans" navigate={navigate}>View all</Link></div><ScanTable compact navigate={navigate} /></article><article className="card"><div className="spaced"><h2 style={{ fontSize: '1.5rem' }}>Scheduled scans</h2><Link to="/schedules" navigate={navigate}>Manage</Link></div>{access.schedule ? <div className="stack-sm">{schedules.slice(0, 2).map((schedule) => <div className="card-flat" key={schedule.name}><div className="spaced"><strong>{schedule.name}</strong><Status value={schedule.state} /></div><p>{schedule.site}<br /><small>Next: {schedule.next}</small></p></div>)}</div> : <p className="muted">Available on paid plans.</p>}</article></section><section className="card" style={{ marginTop: 24 }}><div className="spaced"><div><h2 style={{ fontSize: '1.5rem' }}>Accessibility dates to watch</h2><p className="muted">Informational only; confirm applicability with qualified counsel.</p></div><span className="badge warning">Last verified Sep 1, 2026</span></div><div className="grid-3">{deadlines.map((deadline) => <article className="card-flat" key={deadline.title}><span className="eyebrow">{deadline.market}</span><h3>{deadline.title}</h3><p><strong>{deadline.date}</strong></p><p>{deadline.detail}</p><a href={deadline.source} target="_blank" rel="noreferrer">Authoritative source <ExternalLink size={14} /></a></article>)}</div></section></>;
}

function ScanTable({ navigate, compact = false }: { navigate: Navigate; compact?: boolean }) {
  const rows = compact ? scans.slice(0, 3) : scans;
  return <div className="table-wrap"><table className={compact ? 'compact-table' : undefined}><thead><tr><th>Scan</th><th>Status</th><th>Pages</th><th>{compact ? 'Issues' : 'Violations'}</th>{!compact && <><th>Started</th><th><span className="sr-only">Actions</span></th></>}</tr></thead><tbody>{rows.map((scan) => <tr key={scan.id}><td><MobileLabel>Scan</MobileLabel><div><strong>{scan.site}</strong><br /><small>{scan.id}</small></div></td><td><MobileLabel>Status</MobileLabel><Status value={scan.status} /></td><td><MobileLabel>Pages</MobileLabel>{scan.pages}</td><td><MobileLabel>Violations</MobileLabel><span>{scan.violations} <small>({scan.severe} severe)</small></span></td>{!compact && <><td><MobileLabel>Started</MobileLabel>{scan.date}</td><td><MobileLabel>Actions</MobileLabel><button className="text-link" onClick={() => navigate(`/scans/${scan.id}`)}>View report</button></td></>}</tr>)}</tbody></table></div>;
}

function ScansPage({ navigate, role }: { navigate: Navigate; role: Role }) { return <Gate allowed={entitlements[role].app} title="Sign in to view scans" navigate={navigate}><PageHeading eyebrow="Scan management" title="Scan history" copy="Search, compare, rerun, and inspect your organization’s scan evidence." action={<button className="button" disabled={!entitlements[role].scan} onClick={() => navigate('/scans/new')}><Plus size={18} /> New scan</button>} /><div className="toolbar"><div className="field"><label htmlFor="scan-search">Search scans</label><div className="cluster" style={{ flexWrap: 'nowrap' }}><Search size={18} /><input id="scan-search" type="search" placeholder="URL or scan ID" /></div></div><div className="field"><label htmlFor="scan-status">Status</label><select id="scan-status"><option>All statuses</option><option>Running</option><option>Completed</option><option>Partial</option><option>Failed</option></select></div><div className="field"><label htmlFor="scan-sort">Sort by</label><select id="scan-sort"><option>Newest first</option><option>Most violations</option><option>Site name</option></select></div><button className="button secondary"><Filter size={17} /> More filters</button></div><ScanTable navigate={navigate} /><div className="spaced" style={{ marginTop: 16 }}><small>Showing 1–4 of 4 scans</small><div className="cluster"><button className="button secondary small" disabled>Previous</button><button className="button secondary small" disabled>Next</button></div></div></Gate>; }

function NewScan({ navigate, role }: { navigate: Navigate; role: Role }) {
  const [step, setStep] = useState(1); const [protectedSite, setProtectedSite] = useState(false); const [url, setUrl] = useState('https://app.northstar.example'); const [error, setError] = useState(''); const [started, setStarted] = useState(false);
  const validate = () => { try { const parsed = new URL(url); if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error(); setError(''); setStep(Math.min(4, step + 1)); } catch { setError('Enter a complete HTTP or HTTPS URL.'); } };
  if (started) return <><PageHeading eyebrow="Scan queued" title="Your scan is ready to run" copy="The mock scanner has accepted the sanitized configuration." /><div className="card stack"><Status value="queued" /><h2>app.northstar.example</h2><p>Configuration was sent to the server boundary. Any credential fields were cleared from browser memory and never added to URLs, logs, analytics, fixtures, or persistent client storage.</p><div className="progress" role="progressbar" aria-label="Scan progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={0}><span style={{ width: '2%' }} /></div><div className="cluster"><button className="button" onClick={() => navigate('/scans/SCN-1047')}>Open live details</button><button className="button secondary" onClick={() => setStarted(false)}>Duplicate configuration</button></div></div></>;
  return <Gate allowed={entitlements[role].scan} title="Upgrade to run a scan" navigate={navigate}><PageHeading eyebrow="New scan" title="Configure a site scan" copy={`Your current plan allows up to ${entitlements[role].pageLimit} pages per scan.`} /><ol className="steps" aria-label="Scan setup progress">{['Target', 'Access', 'Scope', 'Review'].map((label, index) => <li key={label} className={step === index + 1 ? 'active' : step > index + 1 ? 'done' : ''} aria-current={step === index + 1 ? 'step' : undefined}>{index + 1}. {label}</li>)}</ol><form className="card stack" onSubmit={(event) => { event.preventDefault(); if (step < 4) validate(); else setStarted(true); }} noValidate>{error && <div className="callout error" role="alert"><strong>Check the highlighted field.</strong><p>{error}</p></div>}{step === 1 && <><div className="field"><label htmlFor="target-url">Website URL</label><input id="target-url" value={url} onChange={(event) => setUrl(event.target.value)} type="url" required aria-invalid={!!error} aria-describedby="url-hint url-error" /><p id="url-hint" className="hint">HTTP and HTTPS only. The server blocks private, loopback, link-local, metadata, and disallowed redirect targets.</p>{error && <p id="url-error" className="error-text">{error}</p>}</div><fieldset><legend>Site access</legend><div className="radio-grid"><label className="radio-card"><input type="radio" name="access" checked={!protectedSite} onChange={() => setProtectedSite(false)} /><span><strong>Public site</strong><br /><small>No sign-in is required.</small></span></label><label className="radio-card"><input type="radio" name="access" checked={protectedSite} onChange={() => setProtectedSite(true)} /><span><strong>Password protected</strong><br /><small>Use a temporary credential or saved server-side secret.</small></span></label></div></fieldset></>}{step === 2 && (protectedSite ? <><div className="field"><label htmlFor="access-method">Access method</label><select id="access-method"><option>Form login</option><option>HTTP Basic authentication</option><option>Saved server-side secret</option></select></div><div className="grid-2"><div className="field"><label htmlFor="scan-user">Username</label><input id="scan-user" autoComplete="off" /></div><div className="field"><label htmlFor="scan-password">Temporary password</label><input id="scan-password" type="password" autoComplete="new-password" /></div></div><div className="callout"><strong>Credential handling</strong><p>One-time credentials remain transient and are destroyed after the scan. Scheduled scans require a separately authorized secret stored encrypted on the server; the browser receives only an opaque reference.</p></div></> : <div className="callout success"><strong>No credentials needed.</strong><p>The scanner will access only public pages within the configured scope.</p></div>)}{step === 3 && <><div className="grid-2"><div className="field"><label htmlFor="page-limit">Page limit</label><input id="page-limit" type="number" min="1" max={entitlements[role].pageLimit} defaultValue={Math.min(200, entitlements[role].pageLimit)} /></div><div className="field"><label htmlFor="crawl-scope">Crawl scope</label><select id="crawl-scope"><option>Same host only</option><option>Exact path and children</option><option>Single page</option></select></div></div><div className="field"><label htmlFor="include">Include paths</label><input id="include" placeholder="/app/**, /account/**" /><p className="hint">Comma-separated glob patterns.</p></div><div className="field"><label htmlFor="exclude">Exclude paths</label><input id="exclude" placeholder="/logout, /admin/**" /></div><label className="cluster"><input type="checkbox" disabled={!entitlements[role].schedule} /> Schedule this configuration after the first run</label>{!entitlements[role].schedule && <p className="hint">Scheduling is not included in this entitlement.</p>}</>}{step === 4 && <><h2>Review configuration</h2><dl className="grid-2"><div><dt>Target</dt><dd>{url}</dd></div><div><dt>Access</dt><dd>{protectedSite ? 'Protected · transient credential' : 'Public'}</dd></div><div><dt>Scope</dt><dd>Same host only · up to {Math.min(200, entitlements[role].pageLimit)} pages</dd></div><div><dt>Schedule</dt><dd>Not scheduled</dd></div></dl><div className="callout warning"><strong>This scan will not certify conformance.</strong><p>Results distinguish automatic findings from manual verification needs.</p></div></>}<div className="form-actions"><button className="button secondary" type="button" onClick={() => step === 1 ? navigate('/scans') : setStep(step - 1)}>{step === 1 ? 'Cancel' : 'Back'}</button><button className="button" type="submit">{step === 4 ? 'Start scan' : 'Continue'} <ChevronRight size={18} /></button></div></form></Gate>;
}

function ScanDetail({ navigate }: { navigate: Navigate }) {
  const [tab, setTab] = useState('summary'); const [cancel, setCancel] = useState(false);
  return <><PageHeading eyebrow="SCN-1047" title="app.northstar.example" copy="Running scan · started Sep 1, 2026 at 1:08 PM CDT" action={<div className="cluster"><button className="button secondary" onClick={() => setCancel(true)}>Cancel scan</button><button className="button secondary"><MoreHorizontal size={18} /><span className="sr-only">More scan actions</span></button></div>} /><div className="card stack"><div className="spaced"><Status value="running" /><strong>78 of 122 discovered pages · 64%</strong></div><div className="progress" role="progressbar" aria-label="Scan progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={64}><span style={{ width: '64%' }} /></div><p className="muted" aria-live="polite">Currently evaluating /account/team. 31 violations found so far; results may change until completion.</p></div><div className="tabs" role="tablist" aria-label="Report sections">{['summary', 'issues', 'pages', 'manual', 'exports'].map((name) => <button key={name} role="tab" aria-selected={tab === name} className={`tab ${tab === name ? 'active' : ''}`} onClick={() => setTab(name)}>{name[0].toUpperCase() + name.slice(1)}</button>)}</div>{tab === 'summary' && <ReportSummary />}{tab === 'issues' && <IssueExplorer />}{tab === 'pages' && <ScanTable navigate={navigate} compact />}{tab === 'manual' && <div className="card"><h2>Manual verification queue</h2><p>18 criteria require review by a qualified person. These are not treated as passes or failures.</p>{issues.filter((issue) => issue.kind === 'Manual verification').map((issue) => <article className="card-flat" key={issue.title}><span className="badge warning">Needs review</span><h3>{issue.title}</h3><p>{issue.explanation}</p></article>)}</div>}{tab === 'exports' && <div className="card stack"><h2>Report exports</h2><p>Exports contain sanitized evidence and clearly label automatic versus manual evaluation. A report export is not a certification.</p><div className="cluster"><button className="button"><Download size={18} /> CSV findings</button><button className="button secondary"><Download size={18} /> Accessible HTML summary</button></div></div>}{cancel && <Dialog title="Cancel this scan?" onClose={() => setCancel(false)}><p>Pages already processed will remain available as a partial result. This action will be recorded in the audit log.</p><div className="form-actions"><button className="button secondary" onClick={() => setCancel(false)}>Keep running</button><button className="button danger" onClick={() => setCancel(false)}>Cancel scan</button></div></Dialog>}</>;
}

function ReportSummary() { return <div className="stack"><div className="grid-4"><article className="card metric"><span className="metric-label">Pages scanned</span><span className="metric-value">78</span><span className="muted">of 122 discovered</span></article><article className="card metric"><span className="metric-label">Violations</span><span className="metric-value">31</span><span className="trend negative">↑ 4 from prior scan</span></article><article className="card metric"><span className="metric-label">Severe issues</span><span className="metric-value">9</span><span className="muted">Critical or serious</span></article><article className="card metric"><span className="metric-label">Manual review</span><span className="metric-value">18</span><span className="muted">No result inferred</span></article></div><div className="grid-2"><article className="card"><h2 style={{ fontSize: '1.4rem' }}>Issue severity</h2><div className="bar-chart" role="img" aria-label="Issue severity: 3 critical, 6 serious, 14 moderate, and 8 minor"><Bar label="Critical" value={3} max={14} /><Bar label="Serious" value={6} max={14} /><Bar label="Moderate" value={14} max={14} /><Bar label="Minor" value={8} max={14} /></div><details><summary>Equivalent data table</summary><table><thead><tr><th>Severity</th><th>Count</th></tr></thead><tbody>{[['Critical',3],['Serious',6],['Moderate',14],['Minor',8]].map(([label, value]) => <tr key={label}><td>{label}</td><td>{value}</td></tr>)}</tbody></table></details></article><article className="card"><h2 style={{ fontSize: '1.4rem' }}>What this means</h2><p>The current automatic findings show focus visibility and text-alternative risks across account and analytics workflows.</p><div className="callout warning"><strong>Partial evidence</strong><p>The crawl is still running and 18 criteria need manual verification. Do not use these totals as a conformance claim.</p></div></article></div></div>; }
function Bar({ label, value, max }: { label: string; value: number; max: number }) { return <div className="bar-row"><span>{label}</span><div className="bar-track"><div className="bar-fill" style={{ width: `${value / max * 100}%` }} /></div><strong>{value}</strong></div>; }

function IssueExplorer() { return <div className="stack"><div className="toolbar"><div className="field"><label htmlFor="issue-search">Search issues</label><input id="issue-search" type="search" placeholder="Criterion, page, element…" /></div><div className="field"><label htmlFor="severity">Severity</label><select id="severity"><option>All severities</option><option>Critical</option><option>Serious</option><option>Moderate</option><option>Minor</option></select></div><div className="field"><label htmlFor="evidence">Evidence type</label><select id="evidence"><option>All evidence</option><option>Automatic</option><option>Manual verification</option></select></div><div className="field"><label htmlFor="group">Group by</label><select id="group"><option>Issue</option><option>Page</option><option>WCAG criterion</option></select></div><button className="button secondary"><Download size={17} /> Export</button></div>{issues.map((issue) => <article className="card issue-card" key={issue.title}><div className="stack-sm"><SeverityLabel value={issue.severity} /><span className={`badge ${issue.kind === 'Automatic' ? 'info' : 'warning'}`}>{issue.kind === 'Automatic' ? <Zap size={14} /> : <Eye size={14} />}{issue.kind}</span></div><div><h2 style={{ fontSize: '1.3rem' }}>{issue.title}</h2><p><strong>{issue.criterion}</strong> · {issue.page} · <code>{issue.element}</code></p><p>{issue.explanation}</p><code className="code">{issue.excerpt}</code><p><strong>Suggested remediation:</strong> {issue.fix}</p></div><button className="button secondary small">Inspect</button></article>)}<div className="spaced"><small>Showing 1–4 of 31 issues</small><div className="cluster"><button className="button secondary small" disabled>Previous</button><button className="button secondary small">Next</button></div></div></div>; }

function SchedulesPage({ navigate, role }: { navigate: Navigate; role: Role }) { const [paused, setPaused] = useState<Record<string, boolean>>({ 'Legacy migration': true }); return <Gate allowed={entitlements[role].schedule} title="Scheduled scans are a paid feature" navigate={navigate}><PageHeading eyebrow="Automation" title="Scan schedules" copy="Create recurring scans and review each next run in your organization’s timezone." action={<button className="button"><Plus size={18} /> New schedule</button>} /><div className="callout"><strong>Timezone: America/Chicago</strong><p>All next-run dates below include the CDT timezone abbreviation.</p></div><div className="grid-3" style={{ marginTop: 20 }}>{schedules.map((schedule) => { const isPaused = paused[schedule.name] ?? schedule.state === 'Paused'; return <article className="card stack-sm" key={schedule.name}><div className="spaced"><Status value={isPaused ? 'Paused' : 'Active'} /><button className="icon-button" aria-label={`More actions for ${schedule.name}`}><MoreHorizontal size={18} /></button></div><h2 style={{ fontSize: '1.35rem' }}>{schedule.name}</h2><p>{schedule.site}<br /><small>{schedule.cadence}</small></p><div><strong>Next run</strong><p>{isPaused ? 'Paused' : schedule.next}</p></div><div className="cluster"><button className="button secondary small" onClick={() => setPaused({ ...paused, [schedule.name]: !isPaused })}>{isPaused ? <Play size={15} /> : <Pause size={15} />} {isPaused ? 'Resume' : 'Pause'}</button><button className="button ghost small"><Settings size={15} /> Edit</button></div></article>; })}</div></Gate>; }

function AcrLibrary({ navigate, role }: { navigate: Navigate; role: Role }) { return <Gate allowed={entitlements[role].acr} title="Upgrade to create draft ACRs" navigate={navigate}><PageHeading eyebrow="Conformance reporting" title="Draft ACR library" copy="Prepare and version draft Accessibility Conformance Reports. Human review is required before a draft can be marked reviewed." action={<button className="button" onClick={() => navigate('/acrs/new')}><Plus size={18} /> New draft ACR</button>} /><div className="table-wrap"><table><thead><tr><th>Name</th><th>Edition</th><th>Version</th><th>Needs review</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{acrs.map((acr) => <tr key={acr.name}><td><MobileLabel>Name</MobileLabel><strong>{acr.name}</strong><small>{acr.updated}</small></td><td><MobileLabel>Edition</MobileLabel>{acr.edition}</td><td><MobileLabel>Version</MobileLabel>{acr.version}</td><td><MobileLabel>Needs review</MobileLabel><span className="badge warning"><Eye size={14} /> {acr.review}</span></td><td><MobileLabel>Status</MobileLabel><Status value={acr.status} /></td><td><MobileLabel>Actions</MobileLabel><button className="text-link" onClick={() => navigate('/acrs/northstar-federal')}>Open</button></td></tr>)}</tbody></table></div><div className="callout warning" style={{ marginTop: 20 }}><strong>Template version: VPAT 2.5Rev (April 2025)</strong><p>The prototype uses ITI’s current four reporting terms: Supports, Partially Supports, Does Not Support, and Not Applicable. “Needs review” is an easyACR workflow state, not an invented VPAT conformance level.</p></div></Gate>; }

function AcrWizard({ navigate, role }: { navigate: Navigate; role: Role }) { const [step, setStep] = useState(1); return <Gate allowed={entitlements[role].acr} title="Upgrade to create draft ACRs" navigate={navigate}><PageHeading eyebrow="New draft ACR" title="Create from scan evidence" copy="Start with completed scans, then evaluate every criterion with the appropriate current template." /><ol className="steps">{['Evidence', 'Market', 'Product', 'Review'].map((label, index) => <li key={label} className={step === index + 1 ? 'active' : step > index + 1 ? 'done' : ''}>{index + 1}. {label}</li>)}</ol><div className="card stack">{step === 1 && <fieldset><legend>Completed scan evidence</legend><div className="radio-grid">{scans.filter((scan) => scan.status === 'completed' || scan.status === 'partial').map((scan) => <label className="radio-card" key={scan.id}><input type="checkbox" defaultChecked={scan.status === 'completed'} /><span><strong>{scan.site}</strong><br /><small>{scan.id} · {scan.status === 'partial' ? 'Partial evidence' : `${scan.pages} pages`}</small></span></label>)}</div></fieldset>}{step === 2 && <fieldset><legend>Target market and VPAT edition</legend><div className="radio-grid"><label className="radio-card"><input type="radio" name="edition" defaultChecked /><span><strong>US federal procurement · VPAT 2.5Rev 508</strong><br /><small>Includes Revised Section 508 requirements and its incorporated WCAG version.</small></span></label><label className="radio-card"><input type="radio" name="edition" /><span><strong>European procurement · VPAT 2.5Rev EU</strong><br /><small>Includes EN 301 549 requirements and is not treated as identical to the 508 edition.</small></span></label><label className="radio-card"><input type="radio" name="edition" /><span><strong>International · VPAT 2.5Rev INT</strong><br /><small>Combines 508, EN 301 549, and WCAG tables.</small></span></label><label className="radio-card"><input type="radio" name="edition" /><span><strong>WCAG · VPAT 2.5Rev WCAG</strong><br /><small>For WCAG-focused reporting without market-specific tables.</small></span></label></div></fieldset>}{step === 3 && <><div className="field"><label htmlFor="product-name">Product name and version</label><input id="product-name" defaultValue="Northstar Platform 8.4" /></div><div className="field"><label htmlFor="product-description">Product description</label><textarea id="product-description" defaultValue="Cloud analytics and reporting platform for distributed operations teams." /></div><div className="field"><label htmlFor="methods">Evaluation methods used</label><textarea id="methods" defaultValue="Automated scanning, manual keyboard review, screen reader testing, contrast analysis, and product-team interviews." /></div></>}{step === 4 && <><div className="callout warning"><strong>27 criteria need review.</strong><p>No conformance result will be inferred where scan evidence is missing or inconclusive.</p></div><dl className="grid-2"><div><dt>Evidence</dt><dd>SCN-1048 · 184 pages</dd></div><div><dt>Template</dt><dd>VPAT 2.5Rev 508</dd></div><div><dt>Product</dt><dd>Northstar Platform 8.4</dd></div><div><dt>Initial state</dt><dd>Draft · human review required</dd></div></dl></>}<div className="form-actions"><button className="button secondary" onClick={() => step === 1 ? navigate('/acrs') : setStep(step - 1)}>{step === 1 ? 'Cancel' : 'Back'}</button><button className="button" onClick={() => step === 4 ? navigate('/acrs/northstar-federal') : setStep(step + 1)}>{step === 4 ? 'Create draft' : 'Continue'} <ChevronRight size={18} /></button></div></div></Gate>; }

function AcrEditor() { const [saved, setSaved] = useState(false); const [reviewed, setReviewed] = useState(false); return <><PageHeading eyebrow="Draft ACR · v0.7" title="Northstar Platform — Federal 2026" copy="VPAT 2.5Rev 508 · 14 unresolved manual-review items" action={<div className="cluster"><button className="button secondary" onClick={() => setSaved(true)}>Save version</button><button className="button" disabled={!reviewed}><Download size={18} /> Export reviewed</button></div>} /><div className="grid-2"><aside className="card stack-sm"><h2 style={{ fontSize: '1.4rem' }}>Document progress</h2><div className="progress" role="progressbar" aria-label="Document review progress" aria-valuemin={0} aria-valuemax={100} aria-valuenow={72}><span style={{ width: '72%' }} /></div><strong>46 of 64 criteria evaluated</strong>{['Product details', 'Evaluation methods', 'WCAG table', 'Functional performance', 'Hardware', 'Software', 'Support documentation'].map((item, index) => <button className="button ghost" key={item} style={{ justifyContent: 'space-between' }}>{item}{index < 3 ? <CheckCircle2 size={17} color="var(--success)" /> : <Eye size={17} />}</button>)}</aside><section className="stack"><div className="callout warning"><strong>Human review gate</strong><p>14 items remain “Needs review.” A reviewed export stays unavailable until every criterion has an allowed template term and supporting explanation.</p></div>{issues.slice(0, 3).map((issue, index) => <article className="card stack" key={issue.criterion}><div className="spaced"><div><span className="eyebrow">Criterion</span><h2 style={{ fontSize: '1.35rem' }}>{issue.criterion}</h2></div><span className={`badge ${index === 2 ? 'warning' : 'info'}`}>{index === 2 ? 'Needs review' : 'Evidence mapped'}</span></div><div className="field"><label htmlFor={`result-${index}`}>Conformance level</label><select id={`result-${index}`} defaultValue={index === 2 ? 'review' : index === 1 ? 'partial' : 'supports'}><option value="review">Needs review (workflow state)</option><option value="supports">Supports</option><option value="partial">Partially Supports</option><option value="does-not">Does Not Support</option><option value="na">Not Applicable</option></select></div><div className="field"><label htmlFor={`remarks-${index}`}>Remarks and explanations</label><textarea id={`remarks-${index}`} defaultValue={index === 2 ? 'Manual contrast and zoom review is pending for the account workflow.' : issue.fix} /></div><details><summary>Supporting evidence</summary><p>{issue.page} · {issue.element} · {issue.kind}</p><code className="code">{issue.excerpt}</code></details></article>)}<label className="radio-card"><input type="checkbox" checked={reviewed} onChange={(event) => setReviewed(event.target.checked)} /><span><strong>I completed the human review step</strong><br /><small>Prototype shortcut: in production, this requires all unresolved criteria to be resolved and records reviewer identity and time.</small></span></label></section></div>{saved && <Toast onClose={() => setSaved(false)}>Version v0.8 saved with an audit event.</Toast>}</>; }

function ToolsPage({ navigate, role }: { navigate: Navigate; role: Role }) { const [connected, setConnected] = useState(true); const [copied, setCopied] = useState(false); const tools = [{ name: 'start_accessibility_scan', description: 'Submit an authorized scan configuration after server-side URL policy checks.' }, { name: 'get_scan_status', description: 'Read progress and non-sensitive status for an organization-scoped scan.' }, { name: 'list_accessibility_issues', description: 'Query sanitized findings with severity, criterion, evidence type, and pagination.' }, { name: 'create_draft_acr', description: 'Create an unevaluated draft workspace from selected completed scans; never finalizes conformance.' }]; return <Gate allowed={entitlements[role].webMcp} title="WebMCP requires an enabled paid entitlement" navigate={navigate}><PageHeading eyebrow="Experimental integration" title="Tools · WebMCP" copy="Allow compatible AI clients to discover and invoke carefully scoped easyACR tools with explicit user control." action={<span className="badge warning">Mock adapter · draft standard</span>} /><div className="callout warning"><strong>Implementation status</strong><p>WebMCP is represented as an experimental browser integration behind feature detection. The prototype does not claim a stable cross-browser API or make live tool registrations.</p></div><div className="grid-3" style={{ marginTop: 20 }}><article className="card"><h3>Access status</h3><p><Status value={connected ? 'Active' : 'Paused'} /></p><p>{connected ? 'Connected to Local AI Client' : 'No active client connection'}</p><button className={`button ${connected ? 'danger' : ''}`} onClick={() => setConnected(!connected)}>{connected ? 'Revoke access' : 'Connect client'}</button></article><article className="card"><h3>Authorization</h3><p>Organization: Northstar Labs<br />Scopes: scans:read, issues:read, drafts:write<br />Expires: Sep 8, 2026</p><button className="button secondary"><KeyRound size={18} /> Rotate authorization</button></article><article className="card"><h3>Recent activity</h3><p><strong>12:44 PM</strong><br />list_accessibility_issues · 24 results</p><p><strong>11:18 AM</strong><br />get_scan_status · SCN-1047</p></article></div><section className="section" style={{ paddingBottom: 0 }}><div className="section-heading"><h2>Available tools</h2><p>Server authorization is evaluated again for every invocation. Tool descriptions are capabilities, not permission grants.</p></div><div className="grid-2">{tools.map((tool) => <article className="card" key={tool.name}><TerminalSquare /><h3><code>{tool.name}</code></h3><p>{tool.description}</p><span className="badge info">Human-visible invocation</span></article>)}</div></section><section className="card stack" style={{ marginTop: 24 }}><div className="spaced"><div><h2 style={{ fontSize: '1.5rem' }}>Connection example</h2><p>Illustrative mock configuration; not a claim of a stable WebMCP wire format.</p></div><button className="button secondary" onClick={() => { void navigator.clipboard?.writeText('https://app.easyacr.example/tools'); setCopied(true); }}><Copy size={18} /> Copy endpoint</button></div><code className="code">{`Mode: WebMCP mock adapter\nOrigin: https://app.easyacr.example\nAuthorization: user-mediated, organization-scoped\nStatus: feature detection required`}</code></section>{copied && <Toast onClose={() => setCopied(false)}>Endpoint copied.</Toast>}</Gate>; }

function AccountPage() { return <><PageHeading eyebrow="Your settings" title="Account and profile" copy="Manage personal preferences separately from organization-level controls." /><form className="card stack"><div className="grid-2"><div className="field"><label htmlFor="name">Name</label><input id="name" defaultValue="Avery Reed" autoComplete="name" /></div><div className="field"><label htmlFor="profile-email">Email</label><input id="profile-email" type="email" defaultValue="avery@northstar.example" autoComplete="email" /></div><div className="field"><label htmlFor="timezone">Timezone</label><select id="timezone" defaultValue="America/Chicago"><option>America/Chicago</option><option>America/New_York</option><option>Europe/Brussels</option></select></div><div className="field"><label htmlFor="market">Primary market</label><select id="market"><option>United States</option><option>European Union</option><option>Both / International</option></select></div></div><fieldset><legend>Notifications</legend><label className="cluster"><input type="checkbox" defaultChecked /> Scan completion and failure emails</label><label className="cluster"><input type="checkbox" defaultChecked /> Upcoming schedule and deadline reminders</label></fieldset><div><button className="button">Save changes</button></div></form></>; }

function BillingPage({ role, setRole }: { role: Role; setRole: (role: Role) => void }) { const usage = role === 'free' || role === 'visitor' ? 0 : 50; return <><PageHeading eyebrow="Plan and usage" title="Subscription and billing" copy="Prototype checkout and billing states. No payment service is connected." /><div className="grid-3"><article className="card"><span className="badge info">Current demo role</span><h2>{roleLabels[role]}</h2><p>Usage this month: {role === 'free' || role === 'visitor' ? '0' : '1,248'} pages</p><div className="progress" role="progressbar" aria-label="Monthly usage" aria-valuemin={0} aria-valuemax={100} aria-valuenow={usage}><span style={{ width: `${usage}%` }} /></div></article><article className="card"><h3>Next invoice</h3><p><strong>Oct 1, 2026</strong><br />$199.00 draft assumption</p><button className="button secondary">View draft invoice</button></article><article className="card"><h3>Payment method</h3><p>Mock Visa ···· 4242<br />Not a real card or charge.</p><button className="button secondary">Update mock method</button></article></div><section className="section" style={{ paddingBottom: 0 }}><div className="grid-3">{draftPlans.map((plan) => <article className={`card pricing-card ${plan.featured ? 'featured' : ''}`} key={plan.name}><span className="badge warning">Draft assumption</span><h2>{plan.name}</h2><p><strong style={{ fontSize: '2rem' }}>{plan.price}</strong> / month</p><p>{plan.pages}</p><button className="button" onClick={() => setRole(plan.name === 'Starter' ? 'paid' : 'admin')}>Use {plan.name} demo</button></article>)}</div></section></>; }

function OrganizationPage({ navigate, role }: { navigate: Navigate; role: Role }) { return <Gate allowed={entitlements[role].organization} title="Organization administration is restricted" navigate={navigate}><PageHeading eyebrow="Admin" title="Organization administration" copy="Manage Northstar Labs members, roles, subscription access, and WebMCP entitlement." action={<button className="button"><Plus size={18} /> Invite member</button>} /><div className="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Plan access</th><th>WebMCP</th><th>Status</th></tr></thead><tbody>{[['Avery Reed','Administrator','Paid','Enabled','Active'],['Morgan Lee','Member','Paid','Enabled','Active'],['Sam Rivera','Member','Paid','Disabled','Invited'],['Jamie Chen','Viewer','Reports only','Disabled','Active']].map((row) => <tr key={row[0]}>{row.map((value, index) => <td key={value}><MobileLabel>{['Member','Role','Plan access','WebMCP','Status'][index]}</MobileLabel>{index === 0 ? <strong>{value}</strong> : value}</td>)}</tr>)}</tbody></table></div><section className="grid-2" style={{ marginTop: 24 }}><article className="card"><h2 style={{ fontSize: '1.4rem' }}>Role policy</h2><p>Administrators manage users, roles, billing, and WebMCP access. They are customer organization administrators—not internal easyACR operators.</p></article><article className="card"><h2 style={{ fontSize: '1.4rem' }}>Audit trail</h2><p>Aug 31 · Avery enabled WebMCP for Morgan<br />Aug 29 · Avery changed Jamie to Viewer<br />Aug 27 · Sam invitation created</p></article></section></Gate>; }

function Onboarding({ navigate }: { navigate: Navigate }) { const [step, setStep] = useState(1); return <main className="auth-shell" id="main"><section className="auth-brand stack"><Logo navigate={navigate} /><span className="eyebrow" style={{ color: '#f7c371' }}>Workspace setup</span><h1>Welcome to easyACR.</h1><p>Three short steps set the market context, team, and first scan without making any conformance claims.</p></section><section className="auth-form"><div className="stack"><ol className="steps">{['Context','Team','Ready'].map((label, index) => <li key={label} className={step === index + 1 ? 'active' : step > index + 1 ? 'done' : ''}>{label}</li>)}</ol>{step === 1 && <><h2>Where do you sell?</h2><fieldset><legend>Procurement context</legend><div className="radio-grid"><label className="radio-card"><input type="checkbox" defaultChecked /> US federal agencies</label><label className="radio-card"><input type="checkbox" /> US state and local government</label><label className="radio-card"><input type="checkbox" /> European Union entities</label></div></fieldset></>}{step === 2 && <><h2>Name your workspace</h2><div className="field"><label htmlFor="org-name">Organization name</label><input id="org-name" defaultValue="Northstar Labs" /></div><div className="field"><label htmlFor="team-size">Team size</label><select id="team-size"><option>2–5 people</option><option>6–25 people</option><option>26+ people</option></select></div></>}{step === 3 && <><div className="feature-icon"><Sparkles /></div><h2>Your workspace is ready</h2><p>Representative data is enabled so you can explore completed, running, partial, failed, and review-required states.</p><div className="callout warning"><strong>Remember</strong><p>Automated testing informs an accessibility evaluation; it cannot certify a product.</p></div></>}<div className="form-actions">{step > 1 ? <button className="button secondary" onClick={() => setStep(step - 1)}>Back</button> : <span /> }<button className="button" onClick={() => step === 3 ? navigate('/dashboard') : setStep(step + 1)}>{step === 3 ? 'Open dashboard' : 'Continue'} <ArrowRight size={18} /></button></div></div></section></main>; }

function Dialog({ title, onClose, children }: { title: string; onClose: () => void; children: ReactNode }) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { ref.current?.focus(); const handler = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler); }, [onClose]); return <div className="dialog-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabIndex={-1} ref={ref}><div className="spaced"><h2 id="dialog-title">{title}</h2><button className="icon-button" onClick={onClose} aria-label="Close dialog"><X size={20} /></button></div>{children}</div></div>; }
function Toast({ onClose, children }: { onClose: () => void; children: ReactNode }) { return <div className="toast" role="status"><div className="spaced"><span>{children}</span><button className="icon-button" onClick={onClose} aria-label="Dismiss message"><X size={18} /></button></div></div>; }

function ErrorPage({ kind, navigate }: { kind: 'denied' | 'not-found' | 'error'; navigate: Navigate }) { const copy = { denied: ['Access denied', 'Your account does not have permission to open this organization resource.'], 'not-found': ['Page not found', 'The page may have moved, or the address may be incorrect.'], error: ['Something went wrong', 'The request could not be completed. Your work has not been lost.'] }[kind]; return <div className="card upgrade-panel stack"><AlertCircle size={48} /><span className="eyebrow">{kind === 'error' ? 'Error EACR-520' : 'Navigation'}</span><h1>{copy[0]}</h1><p>{copy[1]}</p><div className="cluster" style={{ justifyContent: 'center' }}><button className="button" onClick={() => navigate('/dashboard')}>Go to dashboard</button>{kind === 'error' && <button className="button secondary"><RefreshCw size={18} /> Try again</button>}</div></div>; }

function App() {
  const { path, navigate } = useRouter();
  const [theme, setTheme] = useState<'light' | 'dark'>(() => (localStorage.getItem('easyacr-theme') as 'light' | 'dark') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'));
  const [role, setRole] = useState<Role>(() => (localStorage.getItem('easyacr-role') as Role) || 'paid');
  useEffect(() => { document.documentElement.dataset.theme = theme; localStorage.setItem('easyacr-theme', theme); }, [theme]);
  useEffect(() => { localStorage.setItem('easyacr-role', role); }, [role]);
  const publicRoutes = useMemo(() => new Set(['/', '/features', '/pricing', '/about']), []);
  if (path === '/sign-in') return <AuthPage kind="sign-in" navigate={navigate} />;
  if (path === '/sign-up') return <AuthPage kind="sign-up" navigate={navigate} />;
  if (path === '/password-recovery') return <AuthPage kind="recovery" navigate={navigate} />;
  if (path.startsWith('/checkout')) return <AuthPage kind="checkout" navigate={navigate} />;
  if (path === '/onboarding') return <Onboarding navigate={navigate} />;
  if (publicRoutes.has(path)) return <PublicShell path={path} navigate={navigate} theme={theme} setTheme={setTheme}>{path === '/' ? <Home navigate={navigate} /> : path === '/features' ? <Features /> : path === '/pricing' ? <Pricing navigate={navigate} /> : <About />}</PublicShell>;
  const page = path === '/dashboard' ? <Dashboard navigate={navigate} role={role} />
    : path === '/scans' ? <ScansPage navigate={navigate} role={role} />
    : path === '/scans/new' ? <NewScan navigate={navigate} role={role} />
    : path.startsWith('/scans/') ? <ScanDetail navigate={navigate} />
    : path === '/schedules' ? <SchedulesPage navigate={navigate} role={role} />
    : path === '/acrs' ? <AcrLibrary navigate={navigate} role={role} />
    : path === '/acrs/new' ? <AcrWizard navigate={navigate} role={role} />
    : path.startsWith('/acrs/') ? <AcrEditor />
    : path === '/tools' ? <ToolsPage navigate={navigate} role={role} />
    : path === '/account' ? <AccountPage />
    : path === '/billing' ? <BillingPage role={role} setRole={setRole} />
    : path === '/organization' ? <OrganizationPage navigate={navigate} role={role} />
    : path === '/access-denied' ? <ErrorPage kind="denied" navigate={navigate} />
    : path === '/error' ? <ErrorPage kind="error" navigate={navigate} />
    : <ErrorPage kind="not-found" navigate={navigate} />;
  return <AppShell path={path} navigate={navigate} role={role} setRole={setRole} theme={theme} setTheme={setTheme}>{page}</AppShell>;
}

export default App;
